-- Initial Department routing matrix. Apply after EF migrations; safe to rerun.
-- Source workbooks are held outside this repository in backend/docs/Message_Rules.
SET XACT_ABORT ON;
SET NOCOUNT ON;
IF OBJECT_ID(N'orp.DepartmentRoutingRules', N'U') IS NULL
    THROW 51000, 'Apply AddDepartmentRoutingRules migration first.', 1;
BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @Branches TABLE (Name nvarchar(80) NOT NULL PRIMARY KEY);
    IF EXISTS (SELECT 1 FROM @Branches expected JOIN [orp].[Branches] actual ON actual.[Name] COLLATE Latin1_General_100_CI_AS = expected.Name COLLATE Latin1_General_100_CI_AS GROUP BY expected.Name HAVING COUNT(*) > 1)
        THROW 51000, 'A required branch name is ambiguous.', 1;
    SELECT expected.Name FROM @Branches expected
    WHERE NOT EXISTS (SELECT 1 FROM [orp].[Branches] actual WHERE actual.[Name] COLLATE Latin1_General_100_CI_AS = expected.Name COLLATE Latin1_General_100_CI_AS);
    DECLARE @Rules TABLE (DepartmentName nvarchar(80), BranchName nvarchar(80) NULL, Direction int, MatchKind int, MessageTypePattern nvarchar(100), Priority int, SourceFile nvarchar(255), SourceSheet nvarchar(100), SourceRow int);
    IF EXISTS (SELECT 1 FROM @Rules r OUTER APPLY (SELECT COUNT(*) AS Cnt FROM [orp].[Departments] d WHERE d.[Name] COLLATE Latin1_General_100_CI_AS = r.DepartmentName COLLATE Latin1_General_100_CI_AS) m WHERE m.Cnt <> 1)
        THROW 51000, 'A required department is missing or ambiguous.', 1;
    IF EXISTS (SELECT 1 FROM @Rules r OUTER APPLY (SELECT COUNT(*) AS Cnt FROM [orp].[Branches] b WHERE b.[Name] COLLATE Latin1_General_100_CI_AS = r.BranchName COLLATE Latin1_General_100_CI_AS) m WHERE r.BranchName IS NOT NULL AND m.Cnt <> 1)
        THROW 51000, 'A required branch is missing or ambiguous.', 1;
    IF EXISTS (SELECT 1 FROM @Rules GROUP BY DepartmentName, BranchName, Direction, MatchKind, MessageTypePattern HAVING COUNT(*) > 1)
        THROW 51000, 'Duplicate source rules detected.', 1;
    DELETE FROM [orp].[DepartmentRoutingRules] WHERE SourceFile IN (N'CS_Message Processing Review Matrix  Volume.xlsx', N'Message Processing Review Matrix Volume - Data Control 260904.xlsx', N'TFO Message Processing, Review Matrix & Volume.xlsx');
    SELECT d.Id, b.Id, r.Direction, r.MatchKind, r.MessageTypePattern, r.Priority, 1, r.SourceFile, r.SourceSheet, r.SourceRow
    FROM @Rules r JOIN [orp].[Departments] d ON d.[Name] COLLATE Latin1_General_100_CI_AS = r.DepartmentName COLLATE Latin1_General_100_CI_AS
    LEFT JOIN [orp].[Branches] b ON b.[Name] COLLATE Latin1_General_100_CI_AS = r.BranchName COLLATE Latin1_General_100_CI_AS;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
